export const REGION_LABELS: Record<RegionId, string> = {
  'north-america': 'North America',
  'south-america': 'South America',
  europe: 'Europe',
  africa: 'Africa',
  'middle-east': 'Middle East',
  'south-asia': 'South Asia',
  'east-asia': 'East Asia',
  'southeast-asia': 'Southeast Asia',
  'central-asia': 'Central Asia & Caucasus',
  oceania: 'Oceania',
};

export const REGION_IDS = Object.keys(REGION_LABELS) as RegionId[];

const COUNTRY_INDEX: Record<string, CountryProfile> = Object.fromEntries(
  COUNTRIES.map((c) => [c.id, c]),
);

export function getCountry(id: string): CountryProfile | undefined {
  return COUNTRY_INDEX[id];
}

/** Flag CDN — free, no key, and served as real photographic-quality flag art. */
export function flagUrl(iso2: string, width: 20 | 40 | 80 | 160 | 320 | 640 = 160): string {
  return `https://flagcdn.com/w${width}/${iso2.toLowerCase()}.png`;
}

export function flagSvg(iso2: string): string {
  return `https://flagcdn.com/${iso2.toLowerCase()}.svg`;
}
